import json, os, pathlib, subprocess, sys
p=pathlib.Path(sys.argv[1]); marker=(p/'marker').read_text().strip(); home=os.environ['HOME']; cmd=[home+'/.bun/bin/bun','--no-env-file',home+'/.bun/bin/gbrain','serve','--surface','starter','--advertise','verbs'];
with (p/'mcp-stderr.log').open('w') as err:
 with subprocess.Popen(cmd,cwd=home,env={**os.environ,'GBRAIN_HOME':home},stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=err,text=True) as s:
  def rpc(method,params=None,i=None):
   r={'jsonrpc':'2.0','method':method};
   if params is not None: r['params']=params
   if i is not None: r['id']=i
   s.stdin.write(json.dumps(r)+'\n'); s.stdin.flush()
   if i is None: return
   for line in s.stdout:
    v=json.loads(line)
    if v.get('id')==i:
     assert 'error' not in v,v
     return v['result']
   raise RuntimeError('MCP server exited without a response')
  try:
   hello=rpc('initialize',{'protocolVersion':'2025-03-26','capabilities':{},'clientInfo':{'name':'install-check','version':'1'}},1)
   rpc('notifications/initialized'); tools=rpc('tools/list',{},2)['tools']; assert {'remember','recall'} <= {t['name'] for t in tools}
   out=rpc('tools/call',{'name':'recall','arguments':{'grep':marker}},3); assert not out.get('isError') and marker in json.dumps(out) and 'install-check' in json.dumps(out),out
   (p/'mcp-recall.json').write_text(json.dumps(out,indent=2)); print('MCP initialize:',hello['serverInfo']); print('Fresh stdio GBrain recall matched the synthetic marker and install-check provenance.')
  finally:
   s.stdin.close()
   try:s.wait(timeout=5)
   except subprocess.TimeoutExpired:s.terminate(); s.wait(timeout=5)
